        let actual_seq =
            verify_concurrent_submission_binding(&journal, run, value)?;
        observed_sequences.push(actual_seq);
    }
    observed_sequences.sort();
    assert_eq!(observed_sequences, vec![1u64, 2, 3, 4]);
    Ok(())
}

