pub(super) fn read_counter(journal: &FjallJournal) -> Result<Option<u64>, JournalError> {
    match journal.artifact_acceptance.get(b"last_issued")? {
        Some(value) => {
            if value.len() != 8 {
                return Err(JournalError::MalformedKeyspaceRow {
                    prefix: 0,
                    expected_len: 8,
