    match journal.artifact_acceptance.get(b"last_issued")? {
        Some(value) => {
            if value.len() != 8 {
                return Err(JournalError::MalformedKeyspaceRow {
                    prefix: 0,
                    expected_len: 8,
                    actual_len: value.len(),
                });
            }
            let bytes: [u8; 8] =
                value
                    .as_ref()
                    .try_into()
                    .map_err(|_| JournalError::MalformedKeyspaceRow {
                        prefix: 0,
                        expected_len: 8,
                        actual_len: value.len(),
                    })?;
            Ok(Some(u64::from_be_bytes(bytes)))
