    let header = crate::RunHeaderRecord {
        run,
        workflow_id: vb_core::WorkflowId::new(0),
        compiled_digest: workflow.digest(),
        status: 0,
        accepted_at_ms: 1000,
    };
    crate::RunSubmission::new(
        crate::WorkflowSourceRecord {
            digest: source_digest,
            source: source_bytes,
        },
        artifact,
        inputs,
        header,
    )
}

