    let record = journal
        .compiled_ir(inputs.artifact_digest())?
        .ok_or(format!("compiled missing for run {run}"))?;
    assert_eq!(
        record.digest, inputs.artifact_digest(),
        "run {run}: record digest mismatch"
    );
    let decoded: crate::AcceptedArtifact =
        postcard::from_bytes(&record.ir)
            .map_err(|e| format!("run {run}: decode failed: {e}"))?;
    assert_eq!(
        decoded.accepted_at_seq.get(),
        expected_seq,
        "run {run}: artifact seq mismatch"
    );
    assert_eq!(
        decoded.digest, inputs.artifact_digest(),
        "run {run}: artifact digest mismatch"
    );
    assert_eq!(
        decoded.verification.digest, inputs.artifact_digest(),
        "run {run}: verification digest mismatch"
    );

    // Actual admission verification API restores the exact workflow
    let restored =
        crate::admission::verify_accepted_artifact(&decoded)
            .map_err(|e| format!("run {run}: verify failed: {e}"))?;
    assert_eq!(
        &restored, &workflow,
        "run {run}: restored workflow mismatch"
    );

    // RunHeaderRecord: all fields
    let header = journal
        .run_header(run)?
        .ok_or(format!("header missing for run {run}"))?;
    assert_eq!(
        header.run, run,
        "run {run}: header run mismatch"
    );
    assert_eq!(
        header.workflow_id, vb_core::WorkflowId::new(0),
        "run {run}: header workflow_id mismatch"
    );
    assert_eq!(
        header.status, 0,
        "run {run}: header status mismatch"
    );
    assert_eq!(
        header.accepted_at_ms, 1000,
        "run {run}: header accepted_at_ms mismatch"
    );
    assert_eq!(
        header.compiled_digest, expected_workflow_digest,
        "run {run}: header compiled_digest mismatch"
    );

    // Status index row via actual key API
    let status_key = crate::keys::index_status_key(
        crate::types::IndexStatusState::Submitted,
        1000,
        run,
    )?;
    let status_value = journal
        .index_status
        .get(&status_key)?
        .ok_or(format!("run {run}: status index row missing"))?;
    let status_decoded: vb_core::RunId =
        postcard::from_bytes(status_value.as_ref())?;
    assert_eq!(
        status_decoded, run,
        "run {run}: status index value mismatch"
    );

    // Workflow index row via actual key API
    let workflow_key = crate::keys::index_workflow_key(vb_core::WorkflowId::new(0), run)?;
    let workflow_value = journal
        .index_workflow
        .get(&workflow_key)?
        .ok_or(format!("run {run}: workflow index row missing"))?;
    let workflow_decoded: vb_core::RunId =
        postcard::from_bytes(workflow_value.as_ref())?;
    assert_eq!(
        workflow_decoded, run,
        "run {run}: workflow index value mismatch"
    );

